<a class="reading-back" href="<?= $this->h($this->url('/mentor/profile?id='.$mentor['user_id'])) ?>"><?= $this->icon('arrow') ?>پروفایل مرشد</a><header class="schedule-heading"><span class="eyebrow">به وقت تهران</span><h1>زمان‌های مشاورهٔ <?= $this->h($mentor['display_name']) ?></h1><p data-local-date="<?= $this->h($date) ?>"><?= $this->h($date) ?></p></header><p class="notice">درخواست را ثبت کن؛ زمان پس از تأیید مرشد قطعی می‌شود. تماس و چت داخل سامانه هنوز آماده نیست و ورود به اتاق جلسه فعلاً غیرفعال است.</p>
<?php if($dateCorrected): ?><p class="notice">تاریخ لینک قبلی گذشته یا خارج از محدوده بود؛ برنامهٔ فعلی مرشد نمایش داده شد.</p><?php endif; ?>
<section class="card schedule-card section"><h2>روز و مدت گفت‌وگو</h2><form method="get" action="<?= $this->h($this->url('/slots')) ?>"><?php if(!($this->config['pretty_urls']??false)): ?><input type="hidden" name="r" value="/slots"><?php endif; ?><input type="hidden" name="mentor_id" value="<?= $this->h($mentor['user_id']) ?>"><input type="hidden" name="experience_id" value="<?= $this->h($experience_id??'') ?>"><div class="schedule-fields"><div><label for="browse-date">تاریخ</label><input id="browse-date" type="date" name="date" min="<?= $this->h($minDate) ?>" max="<?= $this->h($maxDate) ?>" value="<?= $this->h($date) ?>" required></div><div><label for="browse-duration">مدت گفت‌وگو</label><select name="duration_minutes" id="browse-duration"><option value="15" <?= $duration===15?'selected':'' ?>>۱۵ دقیقه</option><option value="30" <?= $duration===30?'selected':'' ?>>۳۰ دقیقه</option></select></div></div><button>نمایش زمان‌های آزاد</button></form><?php if($nextDate): ?><a class="secondary section" href="<?= $this->h($this->url('/slots?'.http_build_query(['mentor_id'=>$mentor['user_id'],'experience_id'=>$experience_id??'','date'=>$nextDate,'duration_minutes'=>$duration]))) ?>">نزدیک‌ترین روز آزاد: <span data-local-date="<?= $this->h($nextDate) ?>"><?= $this->h($nextDate) ?></span></a><?php endif; ?></section>
<section class="card schedule-card"><h2>انتخاب زمان</h2><?= $this->start('/bookings/create') ?><input type="hidden" name="mentor_id" value="<?= $this->h($mentor['user_id']) ?>"><input type="hidden" name="experience_id" value="<?= $this->h($experience_id??'') ?>"><input type="hidden" name="duration_minutes" value="<?= (int)$duration ?>"><input type="hidden" name="idempotency_key" value="<?= $this->h(bin2hex(random_bytes(16))) ?>"><div class="slot-options"><?php foreach($slots as $s): ?><label class="slot-choice"><input type="radio" name="starts_at" required value="<?= (int)$s['starts_at'] ?>"><span><bdi><?= $this->h($s['label']) ?> — <?= $this->h((new DateTimeImmutable('@'.$s['ends_at']))->setTimezone(new DateTimeZone('Asia/Tehran'))->format('H:i')) ?></bdi></span></label><?php endforeach; ?></div><?php if(!$slots): ?><p>در این روز زمان آزادی وجود ندارد. روز یا مدت گفت‌وگو را در همین صفحه تغییر دهید.</p><?php endif; ?><?php if($slots&&$this->actor): ?><?= $this->field('subject','موضوع گفت‌وگو','text','',true,180) ?><label for="request-need">توضیح کوتاه دربارهٔ نیاز شما</label><textarea id="request-need" name="problem" maxlength="6000" required></textarea><label for="request-method">روش درخواستی</label><select id="request-method" name="requested_method"><option value="chat" selected>چت آنلاین در مرشد</option><option value="audio" <?= \Morshed\Product\MeetingRooms::origin($this->config)?'':'disabled' ?>>تماس صوتی<?= \Morshed\Product\MeetingRooms::origin($this->config)?'':' · به‌زودی' ?></option><option value="video" <?= \Morshed\Product\MeetingRooms::origin($this->config)?'':'disabled' ?>>تماس تصویری<?= \Morshed\Product\MeetingRooms::origin($this->config)?'':' · به‌زودی' ?></option></select><button <?= \Morshed\Product\Consultations::publicBookingOpen()?'':'disabled' ?>><?= \Morshed\Product\Consultations::publicBookingOpen()?'ارسال درخواست مشاوره':'ارسال درخواست · پس از آماده‌شدن برگزاری جلسه' ?></button><?php elseif($slots): ?><a class="primary full" href="<?= $this->h($this->url('/login')) ?>">برای ثبت درخواست وارد شو</a><?php endif; ?></form></section>
